#!/usr/bin/env node
/**
 * Build-time unseal: writes lib/brand-identity.generated.ts from the AES-256-GCM
 * ciphertext in lib/brand-sealed.json. The generated file is gitignored, so the
 * public repository only ever holds ciphertext. Requires BRAND_SEAL_KEY
 * (32 base64 bytes) in the environment or in .env.local.
 */
import { createDecipheriv } from "node:crypto";
import { existsSync, readFileSync, writeFileSync } from "node:fs";

const root = new URL("../", import.meta.url);
const read = (p) => readFileSync(new URL(p, root), "utf8");

function keyFromDotEnv() {
  const path = new URL(".env.local", root);
  if (!existsSync(path)) return "";
  const line = readFileSync(path, "utf8")
    .split("\n")
    .find((l) => l.startsWith("BRAND_SEAL_KEY="));
  return line?.slice("BRAND_SEAL_KEY=".length).trim() ?? "";
}

const key = Buffer.from(process.env.BRAND_SEAL_KEY || keyFromDotEnv(), "base64");
if (key.length !== 32) {
  console.error(
    "BRAND_SEAL_KEY is missing or invalid (need 32 base64-encoded bytes).",
  );
  process.exit(1);
}
const sealed = JSON.parse(read("lib/brand-sealed.json"));
const decipher = createDecipheriv(
  "aes-256-gcm",
  key,
  Buffer.from(sealed.iv, "base64"),
);
decipher.setAuthTag(Buffer.from(sealed.tag, "base64"));
const identity = JSON.parse(
  Buffer.concat([
    decipher.update(Buffer.from(sealed.data, "base64")),
    decipher.final(),
  ]).toString("utf8"),
);

const body = `// GENERATED by scripts/unseal-identity.mjs at build time — do not commit.
export const IDENTITY = ${JSON.stringify(identity, null, 2)} as const;
`;
writeFileSync(new URL("lib/brand-identity.generated.ts", root), body);
console.log("unsealed identity -> lib/brand-identity.generated.ts");
